-- L36-l1-series-fill.sql (lane DLE-SERIES, run O1, owner request of 2026-11-22: no "?" in Otakudle One Piece and Otakudle Dragon Ball, every value correct; generated by gen.py of the lane from the audit, do not edit by hand)
--
-- What:   58 values of character_game_facts (otakudle-one-piece and otakudle-dragon-ball), each set only when the stored value is empty or is the old value listed here, each with a source in docs/o1/reports (changes.csv of the lane):
--         One Piece: 19 bounties (a bounty with no amount in any allowed source is the existing value 0 labelled "No bounty", like L21; Jesus Burgess 20,000,000 as printed in the Rookies saga), 7 seas of origin ("Unknown" for Mihawk, Rayleigh and Uta,
--           whose birthplace no allowed page gives; Yamato and Hatchan Grand Line, Bellamy North Blue, Helmeppo East Blue), the height of Vegapunk (314 cm).
--         Dragon Ball: 5 empty affiliations (Oolong, Puar, Gomah, Glorio, Shin), the race of Hit ("Hit's race", the way Jiren, Ginyu and Zarbon are written), 16 empty home planets ("Unknown" for 14 whose planet no allowed page gives,
--           Planet Vegeta for Vegito and Gogeta, the planet of both fusion halves), the Japanese voice actor hint of Caulifla and Kale, and 7 voice actors that were not those of the first appearance
--           (Mercenary Tao, Uub, Babidi, Korin, Porunga, King Vegeta, General Blue).
--         Two One Piece characters have no height in any allowed source (Imu, Shiki): they leave the pool through dle_curation (excluded, note "L36: ..."), the way the engine already keeps a character out. They were never answers.
--         can_be_target is not touched, so the answers stay 72 (One Piece) and 48 (Dragon Ball); the pool is 98 and 70. updated_at is not touched, so the rollback is exact.
-- Needs:  024, L15, L17, L21. Idempotent: a second run changes nothing; a row that already moved to another value is left alone (warning).
-- WHEN:   apply by the owner after a backup, never during a build, never between 23:50 and 00:30 UTC, one launch file at a time, the Verify lines run after it. The snapshot dle_entities is refreshed in the same transaction;
--         no answer changes (the new values only fill cells that were empty or fix a hint), so the bank is not redrawn.
-- Verify: select count(*) from public.dle_entities e where e.game_id in ('otakudle-one-piece', 'otakudle-dragon-ball') and e.in_pool and (exists (select 1 from public.dle_attributes a where a.game_id = e.game_id and coalesce(cardinality(public.dle_values(e.attrs -> a.key -> 'v')), 0) = 0) or (e.game_id = 'otakudle-one-piece' and nullif(btrim(e.hints ->> 'devil_fruit_name'), '') is null) or (e.game_id = 'otakudle-dragon-ball' and nullif(btrim(e.hints ->> 'signature_technique'), '') is null and nullif(btrim(e.hints ->> 'voice_actor_ja'), '') is null));   expect 0
-- Verify: select count(*) from public.dle_entities where game_id = 'otakudle-one-piece' and in_pool;   expect 98
-- Verify: select count(*) from public.dle_entities where game_id = 'otakudle-dragon-ball' and in_pool;   expect 70
-- Verify: select count(*) from public.dle_entities where game_id = 'otakudle-one-piece' and can_be_target and in_pool;   expect 72
-- Verify: select count(*) from public.dle_entities where game_id = 'otakudle-dragon-ball' and can_be_target and in_pool;   expect 48
-- Verify: select f.attrs -> 'bounty' ->> 'v' from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-one-piece' and c.slug = 'jesus-burgess';   expect 20000000
-- Verify: select f.attrs -> 'height_cm' ->> 'v' from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-one-piece' and c.slug = 'vegapunk';   expect 314
-- Verify: select f.hints ->> 'voice_actor_ja' from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-dragon-ball' and c.slug = 'caulifla';   expect Yuka Komatsu
-- Verify: select f.attrs -> 'home_planet' ->> 'v' from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-dragon-ball' and c.slug = 'frieza';   expect Unknown
-- Verify: select f.hints ->> 'voice_actor_ja' from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-dragon-ball' and c.slug = 'mercenary-tao';   expect Chikao Ōtsuka
-- Verify: select count(*) from public.dle_curation where note like 'L36:%' and excluded;   expect 2
-- Undo:   L36-l1-series-fill.rollback.sql (puts back the exact old values and lets the two characters back into the pool).
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing; a row that already moved to another value is left alone (warning).

do $o1l36$
begin
perform set_config('lock_timeout', '5s', true);
perform set_config('client_min_messages', 'warning', true);

begin
  if to_regclass('public.character_game_facts') is null or to_regclass('public.dle_curation') is null then
    raise exception 'L36: 024 and L15 must be applied first';
  end if;
  if (select count(*) from public.character_game_facts where game_id = 'otakudle-one-piece') < 100 or (select count(*) from public.character_game_facts where game_id = 'otakudle-dragon-ball') < 70 then
    raise exception 'L36: the 100 + 70 facts of L15 are not all there (apply L15 first)';
  end if;
end;

declare
